  function inspectorLayout(){const narrow=matchMedia('(max-width:760px)').matches;if(narrow&&state.detail&&byId(state.selected))return detailView(false);return `<div class="inspector-layout"><section class="compact-list ${narrow?'full-list':''}"><header class="page-header"><div class="grow"><h1>Containers <span class="count-pill">${containers.length}</span></h1><p class="page-subtitle">${countSummary()}</p></div>${ib('plus','Run an image','run')}</header>${toolbar(true)}<div class="main-scroll">${state.scene==='empty'?emptyContainers():disabled()?noEngine():renderGroups(null,true)}</div></section>${narrow?'':state.scene==='connected'&&byId(state.selected)?detailView(true):`<div class="inspector empty">${ico('container',30)}<p>Select a container to inspect it.</p></div>`}</div>`;}
